#!/usr/bin/env bash
set -euo pipefail
ROOT="$(pwd)"
mkdir -p "$(dirname "$ROOT/index.html")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/index.html"
mkdir -p "$(dirname "$ROOT/style.css")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/style.css"
mkdir -p "$(dirname "$ROOT/script.js")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/script.js"
mkdir -p "$(dirname "$ROOT/worker.js")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/worker.js"
mkdir -p "$(dirname "$ROOT/README.md")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/README.md"
mkdir -p "$(dirname "$ROOT/LICENSE")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/LICENSE"
mkdir -p "$(dirname "$ROOT/.gitignore")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' 'LkRTX1N0b3JlClRodW1icy5kYgoqLmxvZwoqLnRtcAouZW52Ci52c2NvZGUvCi5pZGVhLwpiYW5nbGEtb2NyLnppcAo=' > "$ROOT/.gitignore"
mkdir -p "$(dirname "$ROOT/robots.txt")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' 'VXNlci1hZ2VudDogKgpBbGxvdzogLwpTaXRlbWFwOiBodHRwczovL3JhZmFoaW0uY29tL2JhbmdsYS1vY3Ivc2l0ZW1hcC54bWwK' > "$ROOT/robots.txt"
mkdir -p "$(dirname "$ROOT/sitemap.xml")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/sitemap.xml"
mkdir -p "$(dirname "$ROOT/manifest.json")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/manifest.json"
mkdir -p "$(dirname "$ROOT/humans.txt")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/humans.txt"
mkdir -p "$(dirname "$ROOT/.well-known/security.txt")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' 'Q29udGFjdDogbWFpbHRvOmRldkByYWZhaGltLmNvbQpFeHBpcmVzOiAyMDI3LTEwLTA5VDAwOjAwOjAwLjAwMFoKUHJlZmVycmVkLUxhbmd1YWdlczogZW4sIGJuCkNhbm9uaWNhbDogaHR0cHM6Ly9yYWZhaGltLmNvbS8ud2VsbC1rbm93bi9zZWN1cml0eS50eHQKUG9saWN5OiBodHRwczovL3JhZmFoaW0uY29tL2JhbmdsYS1vY3IvCg==' > "$ROOT/.well-known/security.txt"
mkdir -p "$(dirname "$ROOT/favicon.svg")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/favicon.svg"
mkdir -p "$(dirname "$ROOT/og-image.svg")"
python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.argv[1]))' '' > "$ROOT/og-image.svg"
ZIP_PATH="$ROOT/bangla-ocr.zip"
rm -f "$ZIP_PATH"
cd "$ROOT"
FILES=("index.html" "style.css" "script.js" "worker.js" "README.md" "LICENSE" ".gitignore" "robots.txt" "sitemap.xml" "manifest.json" "humans.txt" ".well-known/security.txt" "favicon.svg" "og-image.svg")
for item in "setup.sh" "setup.ps1"; do
  if [[ -f "$item" ]]; then FILES+=("$item"); fi
done
if command -v zip >/dev/null 2>&1; then
  zip -q -r "$ZIP_PATH" "${FILES[@]}"
else
  python3 - "$ZIP_PATH" "${FILES[@]}" <<'PYZIP'
import pathlib, sys, zipfile
out = pathlib.Path(sys.argv[1])
with zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as archive:
    for name in sys.argv[2:]:
        archive.write(name, name)
PYZIP
fi
printf 'Created %s\n' "$ZIP_PATH"
